/* Agency job records. Accounting and payment gateways remain external. */
const todayKey=()=>new Date(Date.now()+2*3600000).toISOString().slice(0,10),cash=n=>Math.round(Number(n)*100),fromCash=n=>n/100;
const normaliseBeforeFinance=normalise;
normalise=function(){normaliseBeforeFinance();for(const a of state.agencies){if(a.accountType==='landlord')a.archivedForAgencyOnly=true;else a.accountType='agency'}if(agencyNow()?.archivedForAgencyOnly){agency=state.agencies.find(a=>!a.archivedForAgencyOnly)?.id||'a1';tenant=state.tenants.find(t=>t.agency===agency)?.id||'';}for(const p of state.properties){p.accessResponsibility??='sevlink';p.accessInstructions??='';p.keyCollection??='';p.parking??='';p.accessRestrictions??=''}for(const j of state.jobs){j.costs??=[];j.financeAudit??=[];for(const i of j.invoices){i.payments??=[];i.issueDate??='';i.dueDate??=''}}};
const jobsBeforeFinance=visibleJobs;visibleJobs=function(){return jobsBeforeFinance().filter(j=>!state.agencies.find(a=>a.id===j.agency)?.archivedForAgencyOnly)};
clientOwner=function(){return 'property agency'};
agencyForm=function(create){const a=create?{}:agencyNow();openForm(create?'Create property agency profile.':'Edit property agency.',field('Agency name','name',a.name)+field('Primary contact','contact',a.contact)+field('Email','email',a.email,'email')+field('Phone','phone',a.phone,'tel')+field('Service area','area',a.area)+'<div class="notice">Agency accounts and linked tenants only. Registration and email invitations are simulated in this demo.</div>',create?'Create demo agency':'Save profile',async d=>{if(await commit(()=>{const values=Object.fromEntries(d);if(create){const a={id:id('a'),...values,accountType:'agency'};state.agencies.push(a);agency=a.id;tenant='';role='manager'}else Object.assign(agencyNow(),values)})){modal.close();navigate('profile');toast('Agency profile saved.')}})};
function accessOwner(j){return j.accessResponsibility||property(j.property)?.accessResponsibility||'sevlink'}
function accessChoiceFields(j){const selected=accessOwner(j);return `<label>Who arranges tenant access?</label><select name="accessResponsibility"><option value="sevlink" ${selected==='sevlink'?'selected':''}>Sevlink to arrange with the tenant</option><option value="agency" ${selected==='agency'?'selected':''}>Agency will arrange access</option></select>`}
function directAccessChoiceFields(props){return `<label>Who arranges tenant access?</label><select name="accessResponsibility"><option value="">Use property default</option><option value="sevlink">Sevlink to arrange with the tenant</option><option value="agency">Agency will arrange access</option></select><label>Access notes for this job (optional)</label><textarea name="accessNotes" rows="2" maxlength="1500"></textarea>`}
propertyForm=function(pid){if(role!=='manager')return;const p=state.properties.find(p=>p.id===pid&&p.agency===agency)||{};openForm(pid?'Edit property & access defaults.':'Add property.',field('Property / unit name','name',p.name)+field('Full address','address',p.address)+`<label>Default access responsibility</label><select name="accessResponsibility"><option value="sevlink" ${p.accessResponsibility!=='agency'?'selected':''}>Sevlink arranges access with the tenant</option><option value="agency" ${p.accessResponsibility==='agency'?'selected':''}>Agency arranges access</option></select>${field('Fallback access contact (optional)','accessContact',p.accessContact,'text',false)}${field('Fallback contact phone (optional)','accessPhone',p.accessPhone,'tel',false)}<label>Access instructions</label><textarea name="accessInstructions" rows="3" maxlength="1500">${esc(p.accessInstructions||'')}</textarea>${field('Key collection (optional)','keyCollection',p.keyCollection,'text',false)}${field('Parking / arrival instructions (optional)','parking',p.parking,'text',false)}${field('Permitted attendance hours / restrictions (optional)','accessRestrictions',p.accessRestrictions,'text',false)}`,'Save property',async d=>{if(!['sevlink','agency'].includes(d.get('accessResponsibility')))return;if(await commit(()=>{if(p.id)Object.assign(p,Object.fromEntries(d));else state.properties.push({id:id('p'),agency,...Object.fromEntries(d)})})){modal.close();navigate('properties');toast('Property and access defaults saved.')}})};
function jobAccessForm(jid){const j=getJob(jid);if(!j||!['manager','sevlink'].includes(role))return;openForm('Access arrangements for this job.',accessChoiceFields(j)+`<label>Job access instructions</label><textarea name="notes" rows="4" maxlength="2000">${esc(j.clientInstructions||property(j.property)?.accessInstructions||'')}</textarea>`,'Save arrangements',async d=>{if(await commit(()=>{j.accessResponsibility=d.get('accessResponsibility');j.clientInstructions=d.get('notes');addEvent(j,'Access arrangements updated',(j.accessResponsibility==='agency'?'Agency':'Sevlink')+' will coordinate access.')})){render();jobDetail(jid,'schedule');toast('Access choice saved for this job.')}})}
function accessSummary(j){const p=property(j.property),t=state.tenants.find(t=>t.id===j.tenant);return `<div class="notice"><b>Access: ${accessOwner(j)==='agency'?'Agency to arrange':'Sevlink to arrange with tenant'}</b><p>${esc(t?.name||p?.accessContact||'Contact to be provided')} ${esc(t?.phone||p?.accessPhone||'')}<br>${esc(j.clientInstructions||p?.accessInstructions||'No additional access instructions.')}${p?.keyCollection?'<br>Key collection: '+esc(p.keyCollection):''}${p?.parking?'<br>Arrival: '+esc(p.parking):''}${p?.accessRestrictions?'<br>Restrictions: '+esc(p.accessRestrictions):''}</p>${role!=='tenant'?`<button class="secondary" onclick="jobAccessForm('${j.id}')">Change access arrangements</button>`:''}</div>`}
function invoicePaid(i){return fromCash((i.payments||[]).filter(p=>p.verification==='Verified').reduce((n,p)=>n+cash(p.amount),0))}
function invoiceBalance(i){return fromCash(Math.max(0,cash(i.amount)-cash(invoicePaid(i))))}
function invoiceState(i){return invoiceBalance(i)===0?'Paid':invoicePaid(i)>0?'Part-paid':'Unpaid'}
function isOverdue(i){return invoiceBalance(i)>0&&!!i.dueDate&&i.dueDate<todayKey()}
function pendingProofs(i){return (i.payments||[]).filter(p=>p.verification==='Pending')}
function findInvoice(jid,iid){const j=getJob(jid);return j?.invoices.find(i=>i.id===iid)}
function invoiceNumberKey(s){return String(s).trim().toUpperCase()}
function duplicateInvoice(number,ignore=''){return state.jobs.some(j=>j.invoices.some(i=>i.id!==ignore&&invoiceNumberKey(i.number)===invoiceNumberKey(number)))}
function validDate(s){return /^\d{4}-\d{2}-\d{2}$/.test(s)&&Number.isFinite(Date.parse(s+'T00:00:00Z'))}
function financialAudit(j,text){j.financeAudit.push({at:now(),by:'Sevlink',text})}
invoiceForm=function(jid){const j=getJob(jid);if(role!=='sevlink'||!j)return;const a=state.agencies.find(a=>a.id===j.agency),follow=j.quotes.find(q=>q.status==='Approved'&&q.approvedForFollowup);openForm('Upload company invoice.',field('Sevlink company invoice number','number')+`<div class="notice">Use the number from your own invoicing system. Gaps are allowed; this website does not allocate invoice numbers.</div><div class="row"><div>${field('Invoice date','issueDate',todayKey(),'date')}</div><div>${field('Due date','dueDate','','date')}</div></div>${field('Bill to','billTo',a.name)}${field('Recipient email','email',a.email,'email')}<label>Total invoice amount (ZAR)</label><input name="amount" type="number" min="0.01" max="10000000" step="0.01" required value="${j.callout?.actualTotal??follow?.amount??''}"><label>Original invoice document (PDF / image, up to 5 MB)</label><input name="file" type="file" required accept="application/pdf,image/jpeg,image/png,image/webp">`,'Upload invoice',async d=>{let file;try{file=await fileData(d.get('file'),quoteTypes)}catch(e){toast(e.message);return}const result=await addCompanyInvoice(jid,{number:d.get('number'),issueDate:d.get('issueDate'),dueDate:d.get('dueDate'),billTo:d.get('billTo'),email:d.get('email'),amount:Number(d.get('amount')),file});if(result){render();jobDetail(jid,'invoices');toast('Invoice recorded as unpaid. No email sent.')}})};
async function addCompanyInvoice(jid,data){const j=getJob(jid);if(!j||role!=='sevlink')return paymentSaveError('Open this invoice from the Sevlink staff profile.');if(!data.number?.trim())return paymentSaveError('Enter the company invoice number.');if(!data.file)return paymentSaveError('Attach the invoice PDF or image before saving.');if(!Number.isFinite(data.amount)||data.amount<=0)return paymentSaveError('Enter a valid invoice amount greater than zero.');if(!validDate(data.issueDate)||!validDate(data.dueDate))return paymentSaveError('Enter both the invoice date and due date.');if(data.dueDate<data.issueDate)return paymentSaveError('The due date cannot be before the invoice date.');if(duplicateInvoice(data.number)){return paymentSaveError('Invoice '+data.number.trim()+' already exists. A separate balance invoice needs its own company invoice number. To record a payment, open Payments / POP on the existing invoice.')}if(j.callout){if(j.status!=='Completed'){toast('Complete this call-out before invoicing.');return false}const follow=j.quotes.find(q=>q.status==='Approved'&&q.approvedForFollowup),cap=cash(j.callout.totalBudget)+(follow?cash(follow.amount):0),existing=j.invoices.reduce((n,i)=>n+cash(i.amount),0);if(existing+cash(data.amount)>cap){toast('This invoice exceeds the approved work amount.');return false}}const i={id:id('i'),...data,amount:fromCash(cash(data.amount)),number:data.number.trim(),payments:[],at:now()};return await commit(()=>{j.invoices.push(i);if(j.status==='Completed')j.finalInvoiceRecorded=true;j.history.push('Company invoice '+i.number+' uploaded.');financialAudit(j,'Invoice '+i.number+' recorded: '+money(i.amount));})?i:false}
renderInvoices=function(j){if(role==='tenant'){$('#jobcontent').innerHTML='<div class="notice">Invoices are managed by the agency and Sevlink.</div>';return}$('#jobcontent').innerHTML=`<h2>Invoices & payment status</h2><p>Record the deposit and remaining balance against the same invoice. Keep its original total and document; do not upload it again to record a payment.</p>${j.invoices.map(i=>`<div class="card" style="margin-bottom:16px"><div class="toolbar"><b style="flex:1">${esc(i.number)}${i.purpose?' · '+esc(i.purpose)+' invoice':''}</b>${badge(invoiceState(i))}${isOverdue(i)?'<span class="badge Urgent">Overdue</span>':''}${role==='sevlink'&&pendingProofs(i).length?'<span class="badge Awaiting">Payment to verify</span>':''}</div><h2 style="margin-top:16px">${money(i.amount)}</h2><p>Invoice date: ${esc(i.issueDate||'Not entered')} · Due: ${esc(i.dueDate||'Not entered')}<br>Verified received: <b>${money(invoicePaid(i))}</b><br>Outstanding: <b>${money(invoiceBalance(i))}</b></p>${!i.purpose&&j.quotes.some(q=>q.status==='Approved')?`<div class="notice">50% deposit target: <b>${money(fromCash(Math.round(cash(i.amount)/2)))}</b><br>${cash(invoicePaid(i))>=Math.round(cash(i.amount)/2)?'Deposit covered by verified payments.':'Deposit still required: '+money(fromCash(Math.max(0,Math.round(cash(i.amount)/2)-cash(invoicePaid(i)))))}</div>`:''}<div class="actions"><button class="secondary" data-download-invoice="${i.id}">Download original invoice</button><button class="secondary" onclick="paymentDetails('${j.id}','${i.id}')">Payments / POP</button>${invoiceBalance(i)>0?`<button class="primary" onclick="paymentForm('${j.id}','${i.id}')">${role==='sevlink'?'Record deposit / balance':'Upload POP'}</button>`:''}<button class="secondary" onclick="invoicePreview('${j.id}','${i.id}')">Email preview</button>${role==='sevlink'?`<button class="secondary" onclick="invoiceDatesForm('${j.id}','${i.id}')">Edit invoice dates</button>`:''}</div></div>`).join('')}${role==='sevlink'?`<button class="primary" onclick="invoiceForm('${j.id}')">＋ Upload company invoice</button>`:''}${!j.invoices.length?'<p>No invoices uploaded yet.</p>':''}<div class="notice">Uploading a POP does not mark an invoice paid. Sevlink verifies received money against the bank transaction. No payment gateway or live email is connected.</div>`;modal.querySelectorAll('[data-download-invoice]').forEach(b=>b.onclick=()=>download(j.invoices.find(i=>i.id===b.dataset.downloadInvoice).file))};
function paymentForm(jid,iid){const i=findInvoice(jid,iid);if(!i||!['manager','sevlink'].includes(role))return;openForm(role==='sevlink'?'Record client payment.':'Upload proof of payment.',`<div id="paymentSaveError" class="notice" role="alert" hidden style="border:2px solid #b42318;color:#b42318"></div><div class="notice">${esc(i.number)} · Outstanding ${money(invoiceBalance(i))}</div><label>Payment type</label><select name="purpose"><option value="Deposit" ${i.purpose!=='Balance'&&invoicePaid(i)===0&&!i.payments.some(p=>p.verification!=='Rejected')?'selected':''}>Deposit (50% for quoted jobs)</option><option value="Balance" ${i.purpose==='Balance'||invoicePaid(i)>0||i.payments.some(p=>p.verification!=='Rejected')?'selected':''}>Balance payment</option><option value="Payment">Other part payment</option></select><p>Record each bank payment on this invoice. A deposit and balance may use the same bank reference.</p><label>Payment amount (ZAR)</label><input name="amount" type="number" min="0.01" max="${invoiceBalance(i)}" step="0.01" value="${invoicePaid(i)===0&&!i.payments.some(p=>p.verification!=='Rejected')&&!i.purpose&&getJob(jid).quotes.some(q=>q.status==='Approved')?fromCash(Math.round(cash(i.amount)/2)):invoiceBalance(i)}" required>${field('Payment date','date',todayKey(),'date')}${field('Payment reference','reference')}<label>POP / supporting document ${role==='manager'?'(required)':'(optional)'}</label><input name="pop" type="file" ${role==='manager'?'required':''} accept="application/pdf,image/jpeg,image/png,image/webp">${role==='sevlink'?'<label style="display:flex;gap:10px;align-items:center"><input name="verified" type="checkbox" style="width:auto">I have checked that this amount was received in the bank account.</label>':'<div class="notice">Sevlink will verify the payment. Until then, it remains pending.</div>'}`,'Save payment record',async d=>{let pop;try{pop=await fileData(d.get('pop'),quoteTypes)}catch(e){paymentSaveError(e.message);return}if(await recordClientPayment(jid,iid,{amount:Number(d.get('amount')),date:d.get('date'),reference:d.get('reference'),purpose:d.get('purpose'),pop,verified:!!d.get('verified')})){render();paymentDetails(jid,iid);toast('Payment record saved.')}});const form=$('#form');form?.addEventListener?.('invalid',e=>{const input=e.target;paymentSaveError(input.name==='amount'?'Enter a valid payment amount, no more than '+money(invoiceBalance(i))+'.':input.name==='reference'?'Enter the bank payment reference.':input.name==='date'?'Choose a valid payment date.':input.name==='pop'?'Attach a supported POP document (PDF, JPG, PNG or WebP).':input.validationMessage||'Complete the required payment fields.');},true)}
function paymentSaveError(message){const box=$('#paymentSaveError');if(box){box.hidden=false;box.textContent=message;box.scrollIntoView?.({block:'nearest'});}toast(message);return false}
async function recordClientPayment(jid,iid,data){const j=getJob(jid),i=j?.invoices.find(i=>i.id===iid);
if(!i||!['sevlink','manager'].includes(role))return paymentSaveError('This invoice is not available in your current profile. Reopen it from Finance.');
if(!Number.isFinite(data.amount)||cash(data.amount)<=0)return paymentSaveError('Enter a payment amount greater than R0.00.');
if(cash(data.amount)>cash(invoiceBalance(i)))return paymentSaveError('The payment is higher than the outstanding balance of '+money(invoiceBalance(i))+'. Enter only the amount received.');
if(!validDate(data.date))return paymentSaveError('Choose a valid payment date.');
if(data.date>todayKey())return paymentSaveError('The payment date is in the future. Choose the date the payment was actually made.');
if(!data.reference?.trim())return paymentSaveError('Enter the bank payment reference. The deposit and balance may use the same reference.');
if(role==='manager'&&!data.pop)return paymentSaveError('Attach the proof of payment before saving.');
const purpose=['Deposit','Balance','Payment'].includes(data.purpose)?data.purpose:'Payment';const p={id:id('pay'),purpose,amount:fromCash(cash(data.amount)),date:data.date,reference:data.reference.trim(),pop:data.pop||null,verification:role==='sevlink'&&data.verified?'Verified':'Pending',submittedBy:role==='sevlink'?'Sevlink':'Agency',at:now()};if(p.verification==='Verified')p.verifiedAt=now();
if(i.payments.some(x=>x.verification!=='Rejected'&&x.date===p.date&&cash(x.amount)===cash(p.amount)&&x.reference===p.reference&&(x.purpose||'Payment')===p.purpose))return paymentSaveError('This '+purpose.toLowerCase()+' is already recorded. For the second payment, select Balance payment. If the first record is pending, verify it under Payments / POP.');
const saved=await commit(()=>{i.payments.push(p);financialAudit(j,'Payment '+p.reference+' '+p.verification.toLowerCase()+': '+money(p.amount));addEvent(j,'Invoice payment '+(p.verification==='Verified'?'verified':'submitted'),i.number+' · '+money(p.amount),'financial')});if(!saved)return paymentSaveError('Browser storage could not save the payment. Your entries are still here. Download your records before clearing any browser data.');return true}

async function verifyClientPayment(jid,iid,pid,accept){const j=getJob(jid),i=j?.invoices.find(i=>i.id===iid),p=i?.payments.find(p=>p.id===pid);if(role!=='sevlink'||!p||p.verification!=='Pending')return false;if(accept&&cash(p.amount)>cash(invoiceBalance(i))){toast('This payment exceeds the remaining invoice balance. Review the records before verifying.');return false}return commit(()=>{p.verification=accept?'Verified':'Rejected';p.verifiedAt=now();financialAudit(j,'Payment '+p.reference+' '+p.verification.toLowerCase());addEvent(j,'Payment '+(accept?'verified':'not confirmed'),i.number+' · '+money(p.amount),'financial')})}
function paymentDetails(jid,iid){const j=getJob(jid),i=j?.invoices.find(i=>i.id===iid);if(!i||role==='tenant')return;modal.innerHTML=`<button class="close" onclick="modal.close()">×</button><span class="eyebrow">INVOICE PAYMENTS</span><h1>${esc(i.number)}</h1>${badge(invoiceState(i))}<p>Invoice ${money(i.amount)} · Verified ${money(invoicePaid(i))}<br>Outstanding ${money(invoiceBalance(i))}</p>${i.payments.map(p=>`<div class="card" style="margin:14px 0"><div class="toolbar"><b>${money(p.amount)}</b>${badge(p.verification)}</div><p><b>${esc(p.purpose||'Payment')}</b><br>${esc(p.date)} · ${esc(p.reference)}<br>Recorded by ${esc(p.submittedBy)}</p><div class="actions">${p.pop?`<button class="secondary" data-pop="${p.id}">Download POP</button>`:''}${role==='sevlink'&&p.verification==='Pending'?`<button class="primary" data-verify="${p.id}">Verify received in bank</button><button class="secondary" data-reject-payment="${p.id}">Not confirmed</button>`:''}${p.verification==='Verified'?`<button class="secondary" onclick="downloadPaymentReceipt('${jid}','${iid}','${p.id}')">Download payment receipt</button>`:''}</div></div>`).join('')||'<p>No payment records yet.</p>'}<div class="actions">${invoiceBalance(i)>0?`<button class="primary" onclick="paymentForm('${jid}','${iid}')">${role==='sevlink'?'Record deposit / balance':'Upload POP'}</button>`:''}<button class="secondary" onclick="jobDetail('${jid}','invoices')">← Back to invoices</button></div>`;if(!modal.open)modal.showModal();modal.querySelectorAll('[data-pop]').forEach(b=>b.onclick=()=>download(i.payments.find(p=>p.id===b.dataset.pop).pop));modal.querySelectorAll('[data-verify]').forEach(b=>b.onclick=async()=>{if(await verifyClientPayment(jid,iid,b.dataset.verify,true)){render();paymentDetails(jid,iid)}});modal.querySelectorAll('[data-reject-payment]').forEach(b=>b.onclick=async()=>{if(await verifyClientPayment(jid,iid,b.dataset.rejectPayment,false)){render();paymentDetails(jid,iid)}})}
function costPaid(c){return fromCash((c.payments||[]).reduce((n,p)=>n+cash(p.amount),0))}
function costBalance(c){return fromCash(Math.max(0,cash(c.amount)-cash(costPaid(c))))}
function jobFinancials(j){const billed=j.invoices.reduce((n,i)=>n+cash(i.amount),0),received=j.invoices.reduce((n,i)=>n+cash(invoicePaid(i)),0),costs=j.costs.reduce((n,c)=>n+cash(c.amount),0);return {billed:fromCash(billed),received:fromCash(received),outstanding:fromCash(billed-received),costs:fromCash(costs),margin:fromCash(billed-costs)}}
function costForm(jid){const j=getJob(jid);if(role!=='sevlink'||!j)return;const b=bookingForEdit(jid),s=b&&bookingSubbie(b);openForm('Record private job cost.',`<label>Cost type</label><select name="type"><option>Subbie</option><option>Materials</option><option>Other</option></select>${field('Supplier / subbie','supplier',s?.name||'')}<label>Actual cost (ZAR)</label><input name="amount" type="number" min="0.01" max="10000000" step="0.01" required value="${b?.price??''}">${field('Supplier invoice / receipt reference','number')}${field('Document date','date',todayKey(),'date')}${field('Payment due (optional)','dueDate','','date',false)}<label>Invoice / receipt (optional, up to 5 MB)</label><input name="file" type="file" accept="application/pdf,image/jpeg,image/png,image/webp"><label>Private notes</label><textarea name="notes" rows="2" maxlength="1500"></textarea><div class="notice">Any booking price shown is an estimate until you save the actual supplier cost. Costs and supplier documents are private to Sevlink.</div>`,'Save actual cost',async d=>{let file;try{file=await fileData(d.get('file'),quoteTypes)}catch(e){toast(e.message);return}if(await addJobCost(jid,{type:d.get('type'),supplier:d.get('supplier'),amount:Number(d.get('amount')),number:d.get('number'),date:d.get('date'),dueDate:d.get('dueDate'),file,notes:d.get('notes')})){render();jobDetail(jid,'finance');toast('Private job cost saved.')}})}
async function addJobCost(jid,data){const j=getJob(jid);if(!j||role!=='sevlink'||!['Subbie','Materials','Other'].includes(data.type)||!data.supplier?.trim()||!data.number?.trim()||!Number.isFinite(data.amount)||data.amount<=0||!validDate(data.date)||data.dueDate&&!validDate(data.dueDate))return false;if(state.jobs.some(x=>x.costs.some(c=>invoiceNumberKey(c.supplier)===invoiceNumberKey(data.supplier)&&invoiceNumberKey(c.number)===invoiceNumberKey(data.number)))){toast('That supplier document is already recorded.');return false}return commit(()=>{j.costs.push({id:id('cost'),...data,amount:fromCash(cash(data.amount)),payments:[],at:now()});financialAudit(j,'Private '+data.type.toLowerCase()+' cost recorded: '+money(data.amount))})}
function costPaymentForm(jid,cid){const j=getJob(jid),c=j?.costs.find(c=>c.id===cid);if(role!=='sevlink'||!c)return;openForm('Record payment to supplier.',`<div class="notice">${esc(c.supplier)} · Outstanding ${money(costBalance(c))}</div><label>Amount paid (ZAR)</label><input name="amount" type="number" min="0.01" max="${costBalance(c)}" step="0.01" required>${field('Payment date','date',todayKey(),'date')}${field('Reference','reference')}<label>Outgoing POP (optional)</label><input name="pop" type="file" accept="application/pdf,image/jpeg,image/png,image/webp">`,'Record outgoing payment',async d=>{let pop;try{pop=await fileData(d.get('pop'),quoteTypes)}catch(e){toast(e.message);return}if(await recordCostPayment(jid,cid,{amount:Number(d.get('amount')),date:d.get('date'),reference:d.get('reference'),pop})){render();jobDetail(jid,'finance');toast('Supplier payment recorded privately.')}})}
async function recordCostPayment(jid,cid,data){const j=getJob(jid),c=j?.costs.find(c=>c.id===cid);if(role!=='sevlink'||!c||!Number.isFinite(data.amount)||data.amount<=0||cash(data.amount)>cash(costBalance(c))||!validDate(data.date)||data.date>todayKey()||!data.reference?.trim())return false;return commit(()=>{c.payments.push({id:id('out'),...data,amount:fromCash(cash(data.amount)),at:now()});financialAudit(j,'Supplier payment recorded: '+money(data.amount))})}
function renderJobFinance(j){if(role!=='sevlink'){$('#jobcontent').innerHTML='<div class="notice">This section is for Sevlink staff only.</div>';return}const f=jobFinancials(j);$('#jobcontent').innerHTML=`<span class="eyebrow">PRIVATE SEVLINK FINANCE</span><div class="cards" style="margin:15px 0">${[['Client invoiced',f.billed],['Verified received',f.received],['Actual direct costs',f.costs],['Job contribution',f.margin]].map(([l,n])=>`<div class="notice"><b>${l}</b><br>${money(n)}</div>`).join('')}</div><p>Job contribution is invoice value less recorded direct costs, before overheads and tax. VAT is not separated here. Booking estimates are not counted twice.</p><div class="actions"><button class="primary" onclick="costForm('${j.id}')">＋ Record supplier / material cost</button><button class="secondary" onclick="jobDetail('${j.id}','invoices')">Client invoices & payments</button></div>${j.costs.map(c=>`<div class="card" style="margin-top:15px"><span class="eyebrow">${esc(c.type)}</span><h2>${esc(c.supplier)}</h2><p>${esc(c.number)} · ${esc(c.date)}<br>Total ${money(c.amount)} · Paid ${money(costPaid(c))}<br><b>Supplier balance ${money(costBalance(c))}</b></p>${c.notes?'<p>'+esc(c.notes)+'</p>':''}<div class="actions">${c.file?`<button class="secondary" data-cost-file="${c.id}">Download supplier document</button>`:'<span class="badge Awaiting">Document not attached</span>'}${costBalance(c)>0?`<button class="secondary" onclick="costPaymentForm('${j.id}','${c.id}')">Record payment to supplier</button>`:'<span class="badge Paid">Supplier paid</span>'}</div>${c.payments.map(p=>`<p class="muted">Paid ${money(p.amount)} on ${esc(p.date)} · ${esc(p.reference)} ${p.pop?`<button class="secondary" data-cost-pop="${c.id}:${p.id}">POP</button>`:''}</p>`).join('')}</div>`).join('')||'<p>No actual supplier costs recorded.</p>'}<details style="margin-top:20px"><summary>Private finance activity</summary>${j.financeAudit.map(a=>`<p>${date(a.at)} · ${esc(a.text)}</p>`).join('')}</details>`;modal.querySelectorAll('[data-cost-file]').forEach(b=>b.onclick=()=>download(j.costs.find(c=>c.id===b.dataset.costFile).file));modal.querySelectorAll('[data-cost-pop]').forEach(b=>b.onclick=()=>{const [cid,pid]=b.dataset.costPop.split(':');download(j.costs.find(c=>c.id===cid).payments.find(p=>p.id===pid).pop)})}
function fileDownload(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadPaymentReceipt(jid,iid,pid){const j=getJob(jid),i=j?.invoices.find(i=>i.id===iid),p=i?.payments.find(p=>p.id===pid);if(!p||role==='tenant'||p.verification!=='Verified')return;const html=`<!doctype html><html><head><meta charset="utf-8"><title>Payment receipt ${esc(i.number)}</title><style>body{max-width:760px;margin:50px auto;padding:20px;font:16px Arial;color:#12345a}h1{border-bottom:3px solid #01b5c1;padding-bottom:20px}p{line-height:1.8}</style></head><body><h1>SEVLINK · Payment acknowledgement</h1><p>Company invoice: <b>${esc(i.number)}</b><br>Job: ${j.ref} · ${esc(property(j.property)?.name)}<br>Bill to: ${esc(i.billTo)}</p><p>Amount received: <b>${money(p.amount)}</b><br>Payment date: ${esc(p.date)}<br>Payment type: ${esc(p.purpose||'Payment')}<br>Reference: ${esc(p.reference)}<br>Verified: ${date(p.verifiedAt||p.at)}</p><p>Invoice total: ${money(i.amount)}<br>Total verified receipts to date: ${money(invoicePaid(i))}<br>Current outstanding balance: ${money(invoiceBalance(i))}<br>Current status: <b>${invoiceState(i)}</b></p><p>This payment acknowledgement accompanies the original invoice. It is not a new invoice.</p></body></html>`;fileDownload(new Blob([html],{type:'text/html'}),'Sevlink-'+i.number.replace(/[^a-z0-9_-]/gi,'_')+'-payment-receipt.html')}
let financeFilter='All',financeSearch='',financeMonth=todayKey().slice(0,7);
function financeInvoices(){if(role==='tenant')return [];return visibleJobs().flatMap(j=>j.invoices.map(i=>({j,i}))).filter(({i})=>financeFilter==='All'||financeFilter==='Overdue'?financeFilter!=='Overdue'||isOverdue(i):financeFilter==='Payment to verify'?pendingProofs(i).length:invoiceState(i)===financeFilter).filter(({j,i})=>`${i.number} ${j.ref} ${property(j.property)?.name} ${state.agencies.find(a=>a.id===j.agency)?.name} ${property(j.property)?.address} ${state.members?.find(m=>m.id===property(j.property)?.manager)?.name} ${state.members?.find(m=>m.id===property(j.property)?.manager)?.email}`.toLowerCase().includes(financeSearch.toLowerCase()))}
function financeContactMarkup(j){const a=state.agencies.find(a=>a.id===j.agency),m=state.members?.find(m=>m.id===property(j.property)?.manager&&m.agency===j.agency);return `<b>${esc(a?.name||'Agency not recorded')}</b><small>PM: ${esc(m?.name||'Unassigned · agency admin')}<br>${esc(m?.phone||a?.phone||'Phone not recorded')}<br>${esc(m?.email||a?.email||'Email not recorded')}</small>`}
function renderFinanceDashboard(){if(role==='manager'&&financeFilter==='Payment to verify')financeFilter='All';if(role==='tenant'){app.innerHTML=heading('Agency / Sevlink access required.','Financial records are not part of the tenant portal.');return}const list=financeInvoices(),all=visibleJobs().flatMap(j=>j.invoices),subbies=visibleJobs().flatMap(j=>j.costs.filter(c=>c.type==='Subbie'&&costBalance(c)>0).map(c=>({j,c})));app.innerHTML=heading(role==='sevlink'?'Invoices, payments & job costs.':'Agency invoices & payments.',role==='sevlink'?'Basic job records for reconciliation and export. Your company invoicing system controls invoice numbers.':'Your agency’s invoices, balances and payment proofs.')+`${role==='sevlink'&&!state.financeDemoLoaded?'<div class="notice">Try the payment flow with clearly labelled sample records. <button class="secondary" onclick="loadFinanceExamples()">Load finance examples</button></div>':''}<div class="stats">${[['Invoiced',all.reduce((n,i)=>n+i.amount,0)],['Verified received',all.reduce((n,i)=>n+invoicePaid(i),0)],['Outstanding',all.reduce((n,i)=>n+invoiceBalance(i),0)],...(role==='sevlink'?[['Payments to verify',all.flatMap(i=>pendingProofs(i)).reduce((n,p)=>n+p.amount,0)]]:[])].map(([l,n])=>`<div class="stat"><label>${l}</label><strong style="font-size:25px">${money(n)}</strong></div>`).join('')}</div><div class="tabs">${['All','Unpaid','Part-paid','Overdue','Paid',...(role==='sevlink'?['Payment to verify','Subbies awaiting payment']:[])].map(s=>`<button class="${financeFilter===s?'selected':''}" onclick="financeFilter='${s}';renderFinanceDashboard()">${s}</button>`).join('')}</div><div class="panel"><input id="financeSearch" aria-label="Search invoices" placeholder="Search invoice, agency, job or property…" style="width:100%;margin-bottom:20px" value="${esc(financeSearch)}">${financeFilter==='Subbies awaiting payment'&&role==='sevlink'?subbies.map(({j,c})=>`<div class="listline toolbar"><div style="flex:1"><b>${esc(c.supplier)}</b><p>${esc(c.number)} · ${esc(property(j.property)?.name)}<br>Outstanding ${money(costBalance(c))}</p></div><button class="secondary" onclick="jobDetail('${j.id}','finance')">Open private costs</button></div>`).join('')||'<p>No subbie balances outstanding.</p>':`<div class="tablewrap"><table><thead><tr><th>COMPANY INVOICE / PROPERTY / JOB</th><th>AGENCY / PM CONTACT</th><th>STATUS</th><th>OUTSTANDING</th><th>DUE</th><th></th></tr></thead><tbody>${list.map(({j,i})=>`<tr onclick="jobDetail('${j.id}','invoices')"><td><strong>${esc(i.number)}</strong><small><b>${esc(property(j.property)?.address)}</b><br>${esc(property(j.property)?.name)} · ${j.ref}<br>${esc(j.title)}<br>Invoice total ${money(i.amount)} · Received ${money(invoicePaid(i))}</small></td><td>${financeContactMarkup(j)}</td><td>${badge(invoiceState(i))}${isOverdue(i)?' '+badge('Overdue'):''}${role==='sevlink'&&pendingProofs(i).length?' '+badge('Payment to verify'):''}</td><td>${money(invoiceBalance(i))}</td><td>${esc(i.dueDate||'Not entered')}</td><td>↗</td></tr>`).join('')||'<tr><td colspan="6">No invoices in this view.</td></tr>'}</tbody></table></div>`}</div>${role==='sevlink'?`<div class="panel" style="margin-top:20px"><h2>Monthly records export</h2><p>Download invoice, receipt, supplier-cost and payment records for your separate bookkeeping system.</p><div class="toolbar"><input type="month" id="financeMonth" value="${financeMonth}"><button class="secondary" onclick="exportFinanceCSV()">Download CSV</button><button class="primary" onclick="exportFinanceBundle()">Download records + documents ZIP</button></div></div>`:''}<div class="notice">Browser demo only. No bank feed, card processing, accounting sync or live email. Keep independent copies of your real records.</div>`;$('#financeSearch').oninput=e=>{financeSearch=e.target.value;renderFinanceDashboard();$('#financeSearch').focus()};if($('#financeMonth'))$('#financeMonth').onchange=e=>financeMonth=e.target.value}
const stageBeforeFinance=jobStage;jobStage=function(j){if(j.status==='Completed'&&j.invoices.length&&j.completedAt&&j.completionNotes){return j.invoices.some(i=>invoiceBalance(i)>0||pendingProofs(i).length)?'payment':'closed'}return stageBeforeFinance(j)};
if(!stages.some(s=>s[0]==='payment'))stages.splice(stages.findIndex(s=>s[0]==='closed'),0,['payment','Awaiting payment','Invoice issued; verify receipts']);
const nextBeforeFinance=nextAction;nextAction=function(j){if(jobStage(j)==='payment')return j.invoices.some(i=>pendingProofs(i).length)?'Verify payment proof against bank receipt':'Await payment / record money received';return nextBeforeFinance(j)};
function csvCell(v){if(typeof v==='number')return String(v);let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function monthlyFinanceData(month){if(role!=='sevlink'||!/^\d{4}-\d{2}$/.test(month))return {rows:[],files:[]};const rows=[['Type','Date','Agency','Property','Job','Property address','Property manager','PM phone','PM email','Document number','Party','Amount ZAR','Verified paid ZAR','Outstanding ZAR','Status','Reference']],files=[];const addFile=(path,file)=>{if(file?.data)files.push({name:path+'/'+safeFinanceName(file.name),file})};for(const j of visibleJobs()){const a=state.agencies.find(a=>a.id===j.agency),p=property(j.property),pm=state.members?.find(m=>m.id===p?.manager&&m.agency===j.agency),prefix=[a?.name,p?.name,j.ref,p?.address,pm?.name||'Agency admin',pm?.phone||a?.phone,pm?.email||a?.email];for(const i of j.invoices){if((i.issueDate||i.at?.slice(0,10)||'').startsWith(month)){rows.push(['Client invoice',i.issueDate,...prefix,i.number,i.billTo,i.amount,invoicePaid(i),invoiceBalance(i),invoiceState(i)+(i.issueDate?'':' — invoice date not captured'),'']);addFile(j.ref+'/client-invoices/'+safeFinanceName(i.number),i.file)}for(const pay of i.payments)if(pay.date.startsWith(month)){rows.push(['Client payment',pay.date,...prefix,i.number,i.billTo,pay.amount,pay.verification==='Verified'?pay.amount:0,'',pay.verification,pay.reference]);addFile(j.ref+'/client-payments/'+safeFinanceName(pay.id),pay.pop)}}for(const c of j.costs){if(c.date.startsWith(month)){rows.push([c.type+' cost',c.date,...prefix,c.number,c.supplier,c.amount,costPaid(c),costBalance(c),costBalance(c)===0?'Paid':costPaid(c)>0?'Part-paid':'Unpaid','']);addFile(j.ref+'/supplier-documents/'+safeFinanceName(c.id),c.file)}for(const pay of c.payments)if(pay.date.startsWith(month)){rows.push(['Supplier payment',pay.date,...prefix,c.number,c.supplier,pay.amount,pay.amount,'','Recorded',pay.reference]);addFile(j.ref+'/supplier-payments/'+safeFinanceName(pay.id),pay.pop)}}}return {rows,files}}
function safeFinanceName(s){return String(s||'document').replace(/[^a-z0-9._-]/gi,'_').replace(/^\.+/,'')||'document'}
function csvData(rows){return '\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')}
function exportFinanceCSV(){if(role!=='sevlink')return;const {rows}=monthlyFinanceData(financeMonth);fileDownload(new Blob([csvData(rows)],{type:'text/csv;charset=utf-8'}),'Sevlink-records-'+financeMonth+'.csv')}
function crc32(bytes){let c=0xffffffff;for(const b of bytes){c^=b;for(let n=0;n<8;n++)c=(c>>>1)^((c&1)?0xedb88320:0)}return (c^0xffffffff)>>>0}
function createStoredZip(files){const encoder=new TextEncoder(),parts=[],central=[];let offset=0;for(const f of files){const name=encoder.encode(f.name),data=f.bytes,crc=crc32(data),local=new Uint8Array(30+name.length),lv=new DataView(local.buffer);lv.setUint32(0,0x04034b50,true);lv.setUint16(4,20,true);lv.setUint16(6,0x0800,true);lv.setUint16(12,0x21,true);lv.setUint32(14,crc,true);lv.setUint32(18,data.length,true);lv.setUint32(22,data.length,true);lv.setUint16(26,name.length,true);local.set(name,30);parts.push(local,data);const record=new Uint8Array(46+name.length),rv=new DataView(record.buffer);rv.setUint32(0,0x02014b50,true);rv.setUint16(4,20,true);rv.setUint16(6,20,true);rv.setUint16(8,0x0800,true);rv.setUint16(14,0x21,true);rv.setUint32(16,crc,true);rv.setUint32(20,data.length,true);rv.setUint32(24,data.length,true);rv.setUint16(28,name.length,true);rv.setUint32(42,offset,true);record.set(name,46);central.push(record);offset+=local.length+data.length}const centralSize=central.reduce((n,p)=>n+p.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,files.length,true);ev.setUint16(10,files.length,true);ev.setUint32(12,centralSize,true);ev.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/zip'})}
function exportFinanceBundle(){if(role!=='sevlink')return;const {rows,files}=monthlyFinanceData(financeMonth),encoder=new TextEncoder(),bundle=[{name:'Sevlink-records-'+financeMonth+'.csv',bytes:encoder.encode(csvData(rows))},{name:'README.txt',bytes:encoder.encode('Sevlink job records export.\nPeriod: '+financeMonth+'\nCompany invoice numbers come from your invoicing system.\nClient payments marked Pending are unverified claims, not confirmed receipts.\nSupplier costs and outgoing payments are private records.\nDocuments are originals uploaded to the job. Missing documents must be obtained separately.\nThis export does not file tax returns or calculate VAT.')}];for(const f of files){const raw=f.file.data.split(',')[1];if(raw)bundle.push({name:f.name,bytes:Uint8Array.from(atob(raw),c=>c.charCodeAt(0))})}fileDownload(createStoredZip(bundle),'Sevlink-records-'+financeMonth+'.zip')}
const rowsBeforeFinance=rows;rows=function(){if(role!=='manager')return rowsBeforeFinance();const list=visibleJobs().filter(j=>(filter==='All statuses'||filter===j.status)&&`${j.ref} ${j.title} ${property(j.property)?.name} ${property(j.property)?.address}`.toLowerCase().includes(query.toLowerCase()));$('#rows').innerHTML=list.map(j=>{const p=property(j.property);return `<tr tabindex="0" data-job="${j.id}"><td><strong class="agent-address">${esc(p?.address||p?.name)}</strong><span class="agent-unit">${esc(p?.name)}</span><div class="agent-need"><b>Repair needed:</b> ${esc(j.title)}</div><small>${j.ref} · ${esc(j.category)}</small></td><td>${badge(j.priority)}</td><td>${badge(jobStatusLabel(j))}</td><td>↗</td></tr>`}).join('')||'<tr><td colspan="4" class="empty">No matching jobs.</td></tr>';$('#rows').onclick=e=>{const r=e.target.closest('[data-job]');if(r)jobDetail(r.dataset.job)};$('#rows').onkeydown=e=>{if(e.key==='Enter'){const r=e.target.closest('[data-job]');if(r)jobDetail(r.dataset.job)}}};
reviewInboxMarkup=function(){const jobs=tenantReviewJobs();return `<div class="panel review-inbox" style="margin-top:22px"><h2>Tenant reports to review <span class="badge">${jobs.length}</span></h2><p>Complete the details, choose the service and send to Sevlink.</p>${jobs.map(j=>{const p=property(j.property);return `<div class="listline toolbar"><div style="flex:1"><strong class="agent-address">${esc(p?.address||p?.name)}</strong><span class="agent-unit">${esc(p?.name)}</span><p><b>Repair needed:</b> ${esc(j.title)}<br>${j.ref} · ${esc(state.tenants.find(t=>t.id===j.tenant)?.name)}</p></div><button class="primary" onclick="reviewTenantReportForm('${j.id}')">Review & send to Sevlink</button></div>`}).join('')||'<p>No reports waiting for review.</p>'}</div>`};
const renderBeforeFinance=render;render=function(){renderBeforeFinance();if(!state)return;if($('#newAgency'))$('#newAgency').textContent='＋ Create agency profile';if(role!=='tenant')$('#nav').insertAdjacentHTML('beforeend',`<button data-view="finance" class="${view==='finance'?'active':''}">R &nbsp; ${role==='sevlink'?'Finance & payments':'Invoices & payments'}</button>`);if(view==='finance')renderFinanceDashboard();if(role==='manager'&&['overview','requests'].includes(view)){const header=$('table th');if(header)header.textContent='PROPERTY ADDRESS / REPAIR NEEDED'}};
const detailBeforeFinance=jobDetail;jobDetail=function(jid,section='comments'){detailBeforeFinance(jid,section);const j=getJob(jid);if(!j)return;if(section==='finance')renderJobFinance(j);if(role==='sevlink')$('.tabs').insertAdjacentHTML('beforeend',`<button onclick="jobDetail('${jid}','finance')" class="${section==='finance'?'selected':''}">Private costs & margin</button>`);if(section==='schedule'||section==='comments')$('#jobcontent').insertAdjacentHTML('afterbegin',accessSummary(j))};

function invoiceDatesForm(jid,iid){const j=getJob(jid),i=j?.invoices.find(i=>i.id===iid);if(role!=='sevlink'||!i)return;openForm('Edit invoice dates.',`<div class="notice">${esc(i.number)} · Use the dates on your original invoice.</div>${field('Invoice date','issueDate',i.issueDate,'date')}${field('Due date','dueDate',i.dueDate,'date')}`,'Save invoice dates',async d=>{if(!validDate(d.get('issueDate'))||!validDate(d.get('dueDate'))||d.get('dueDate')<d.get('issueDate'))return;if(await commit(()=>{i.issueDate=d.get('issueDate');i.dueDate=d.get('dueDate');financialAudit(j,'Invoice dates updated for '+i.number)})){render();jobDetail(jid,'invoices')}})}

function financeDemoFile(name,label){const text='<svg xmlns="http://www.w3.org/2000/svg" width="700" height="300"><rect width="700" height="300" fill="#f3f8fc"/><rect width="700" height="55" fill="#063563"/><text x="25" y="36" fill="white" font-family="Arial" font-size="22">SEVLINK — DEMONSTRATION DOCUMENT</text><text x="25" y="110" fill="#063563" font-family="Arial" font-size="20">'+esc(label)+'</text><text x="25" y="160" fill="#607c92" font-family="Arial" font-size="16">Example only. Not an actual invoice or bank payment.</text></svg>';return {name,type:'image/svg+xml',data:'data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(text)))}}
async function loadFinanceExamples(){if(role!=='sevlink'||state.financeDemoLoaded)return;const p=state.properties.find(p=>p.id==='p1');if(!p){toast('No example property available.');return}const day=todayKey(),due=new Date(Date.parse(day+'T00:00:00Z')-3*86400000).toISOString().slice(0,10),issued=due.slice(0,8)+'01';const invoice=(number,amount,payments)=>({id:id('i'),number,amount,billTo:'Oak & River Properties · DEMO',email:'office@example.com',issueDate:issued,dueDate:due,at:now(),payments,file:financeDemoFile(number+'.svg',number+' · R '+amount)});const payment=(amount,status,reference)=>({id:id('pay'),amount,date:day,reference,verification:status,submittedBy:'DEMO',at:now(),verifiedAt:status==='Verified'?now():null,pop:financeDemoFile(reference+'.svg','DEMO proof: '+reference)});const j={id:id('demo-finance'),ref:'DEMO-FINANCE',agency:p.agency,property:p.id,tenant:'t1',title:'Demo: invoice and payment tracking',description:'Clearly labelled finance examples; no actual money has moved.',category:'General maintenance',priority:'Normal',status:'Completed',sentToSevlink:true,assigned:true,team:'Sevlink Repairs Team',photos:[],beforePhotos:[],afterPhotos:[],comments:[],quotes:[],schedule:null,events:[],history:[],createdAt:now(),completedAt:now(),completionNotes:'Demo work report.',completionChecks:'Example only.',invoices:[invoice('DEMO-INV-PART',3000,[payment(1000,'Verified','DEMO-PART-RECEIPT')]),invoice('DEMO-INV-PAID',1200,[payment(1200,'Verified','DEMO-FULL-RECEIPT')]),invoice('DEMO-INV-PENDING',800,[payment(800,'Pending','DEMO-PENDING-POP')])],costs:[{id:id('cost'),type:'Subbie',supplier:'DEMO PRIVATE SUPPLIER',amount:2000,number:'DEMO-SUB-1',date:issued,dueDate:due,at:now(),notes:'Private cost example.',file:financeDemoFile('DEMO-SUB-1.svg','Demo supplier invoice · R 2000'),payments:[{id:id('out'),amount:500,date:day,reference:'DEMO-SUB-PAYMENT',at:now(),pop:financeDemoFile('DEMO-SUB-PAYMENT.svg','Demo outgoing payment · R 500')}]},{id:id('cost'),type:'Materials',supplier:'DEMO MATERIALS SHOP',amount:250,number:'DEMO-RECEIPT-1',date:issued,dueDate:'',at:now(),notes:'Private materials receipt.',file:financeDemoFile('DEMO-RECEIPT-1.svg','Demo materials receipt · R 250'),payments:[]}],financeAudit:[],accessResponsibility:'sevlink',access:{status:'Confirmed',note:'Demo access arrangements.'}};if(await commit(()=>{state.jobs.push(j);state.financeDemoLoaded=true})){render();toast('Finance examples loaded. No real payments recorded.')}}

